package mrpapermoon.whisper.mesh.nearbyimport kotlinx.coroutines.CancellationExceptionimport kotlinx.coroutines.channels.SendChannelimport mrpapermoon.whisper.mesh.db.RumorDatabaseimport mrpapermoon.whisper.mesh.db.WhispererEntityimport mrpapermoon.whisper.mesh.transformation.deserializeimport mrpapermoon.whisper.mesh.transformation.serializeimport mrpapermoon.whisper.service.NearbyConnectionEventinternal class EndpointConnectionHolder(	actor: SendChannel<ByteArray>,	private val userName: String,	private val userCipher: ByteArray,	private val database: RumorDatabase,	private val endpointId: String,) : SendChannel<ByteArray> by actor {	private val networkMessageDao by lazy { database.networkMessageDao() }	private val whispererDao by lazy { database.whispererDao() }	@Volatile	private var isOutgoing: Boolean = false	/*	Communication scheme		| Caller (outgoing call)    | Answerer (incoming call)  |		+---------------------------+---------------------------+		Greeting    ················>   Greeting					<················		****Request ················>   ****Response					<················		Gratitude   ················>		****Response    <············   ****Request						············>					<················   Gratitude	 */	suspend fun onEvent(value: NearbyConnectionEvent) {		when (value) {			is NearbyConnectionEvent.OnBytesPayloadReceived -> {				// TODO: чтобы не зациклились нужно помнить кто host. а лучше не помнить и в request сразу отдавать нужную data				val response: NearbyMessage = when (val message = NearbyMessage.deserialize(value.payload)) {					is NearbyMessage.Greeting -> {						if (message.version != NearbyMessage.VERSION) {							leave { "Versions doesn't match(version: ${message.version}, VERSION: ${NearbyMessage.VERSION})" }						}						val whisperer = whispererDao.getWhisperer(endpointId)							?.let { it.copy(decryptionKeys = it.decryptionKeys + message.decryptionKey) }							?: WhispererEntity(endpointId, message.name, setOf(message.decryptionKey))						whispererDao.insert(whisperer)						if (isOutgoing) getContactsRequest() else getGreeting()					}					is NearbyMessage.ContactsRequest -> {						val whisperersByIds = whispererDao.getWhisperersByIds(message.whispererIds)						NearbyMessage.ContactsResponse(whisperersByIds)					}					is NearbyMessage.ContactsResponse -> {						val contacts = message.contacts						// TODO: вместо insert должен быть merge and insert						whispererDao.insertAll(contacts)						// TODO: где живет karmaTree? для этого запоминаем contacts каждого contact до 7го колена						// TODO: искать не по всем контактам, а только по известным ключам						NearbyMessage.RumorsRequest(contacts.map { it.whispererId })					}					is NearbyMessage.RumorsRequest -> {						val messageEntities = networkMessageDao.getMessagesByWhispererId(message.whispererIds)						NearbyMessage.RumorsResponse(messageEntities)					}					is NearbyMessage.RumorsResponse -> {						// TODO: переопределить onConflict						networkMessageDao.insertAll(message.rumors)						if (isOutgoing) {							NearbyMessage.Gratitude						} else {							leave()						}					}					is NearbyMessage.Gratitude -> {						if (isOutgoing) {							leave()						} else {							getContactsRequest()						}					}				}				send(response.serialize())			}			is NearbyConnectionEvent.OnConnection -> {				// TODO: что если соеденение не host-participant а два односторонних канала?				isOutgoing = value.imHosting				if (isOutgoing) {					send(getGreeting().serialize())				}			}			is NearbyConnectionEvent.OnDisconnected -> {				close(CancellationException("Connection w/ ${value.endpointId} was lost"))			}			is NearbyConnectionEvent.OnDropConnection -> {				close(CancellationException("Connection w/ ${value.endpointId} was dropped"))			}			is NearbyConnectionEvent.OnFlowPayloadReceived -> TODO()		}	}	private fun getGreeting(): NearbyMessage.Greeting = NearbyMessage.Greeting(NearbyMessage.VERSION, userName, userCipher)	private suspend fun getContactsRequest(): NearbyMessage.ContactsRequest {		val allWhisperers = whispererDao.getAllWhisperers().map { it.whispererId }		return NearbyMessage.ContactsRequest(allWhisperers)	}	private fun leave(causeDescription: (() -> String)? = null): Nothing {		val cause = causeDescription?.let { getter -> CancellationException(getter()) }		close(cause)		throw ConnectionComplete()	}	class ConnectionComplete : CancellationException()}